  "starter_code": "class MinStack:\n    def __init__(self):\n        \"\"\"\n        Initializes an empty stack.\n        \"\"\"\n        pass\n\n    def push(self, val):\n        \"\"\"\n        val: int\n        Returns: None\n        \"\"\"\n        pass\n\n    def pop(self):\n        \"\"\"\n        Removes the top element. Returns: None\n        \"\"\"\n        pass\n\n    def top(self):\n        \"\"\"\n        Returns: int -- the top element.\n        \"\"\"\n        pass\n\n    def getMin(self):\n        \"\"\"\n        Returns: int -- the current minimum element on the stack.\n        \"\"\"\n        pass\n",
